#include <cstdio>
#include <cstdlib>
#include <climits>
#include <algorithm>
#include <vector>

using namespace std;

const int MAXN = 50;
const int MAXM = 50;
const int MAXK = 50;
const int T_val = MAXN + MAXK + 1;
const int NN = MAXN * T_val + 1;
const int MM = MAXK + (MAXM * 2 * MAXK + MAXN) * (T_val - 1);
const int INF = 0x3f3f3f3f;

struct adj_node {
	adj_node* next;
	int node;
};

adj_node aa[MAXN], aa_[NN];
adj_node* pool1 = nullptr;
adj_node* pool2 = nullptr;

int pi[NN], kk[NN], bb[NN];
int pq[NN + 1], iq[NN], pq_size;

inline bool lt(int u, int v) {
	return pi[u] < pi[v] || (pi[u] == pi[v] && kk[u] < kk[v]);
}

int get_child(int i) {
	i *= 2;
	if (i > pq_size) return 0;
	if (i < pq_size && lt(pq[i+1], pq[i])) return i+1;
	return i;
}

void heap_up(int u) {
	int i = iq[u];
	int j;
	while ((j = i / 2) && lt(u, pq[j])) {
		pq[iq[pq[j]] = i] = pq[j];
		i = j;
	}
	pq[iq[u] = i] = u;
}

void heap_down(int u) {
	int i = iq[u];
	int j;
	while ((j = get_child(i)) && lt(pq[j], u)) {
		pq[iq[pq[j]] = i] = pq[j];
		i = j;
	}
	pq[iq[u] = i] = u;
}

void heap_insert(int u) {
	iq[u] = ++pq_size;
	heap_up(u);
}

int heap_extract() {
	int u = pq[1];
	int v = pq[pq_size--];
	iq[v] = 1;
	heap_down(v);
	return u;
}

void add_edge(int i, int j) {
	if (!pool1) pool1 = (adj_node*)malloc(sizeof(adj_node) * (MAXM * 2 + 1)), pool1--;
	pool1->node = j;
	pool1->next = aa[i].next;
	aa[i].next = pool1++;
}

void add_edge_graph2(int i, int h) {
	if (!pool2) pool2 = (adj_node*)malloc(sizeof(adj_node) * (MM * 2 + 1)), pool2--;
	pool2->node = h;
	pool2->next = aa_[i].next;
	aa_[i].next = pool2++;
}

int n_nodes, m_edges;
int U[MM], V[MM], UV[MM], COST[MM], COST_red[MM];
int CAP[MM * 2];

void add_link(int u, int v, int cap, int cos) {
	int h = m_edges++;
	U[h] = u; V[h] = v; UV[h] = u ^ v;
	COST[h] = cos;
	CAP[h << 1 ^ 0] = cap;
	add_edge_graph2(u, h << 1 ^ 0);
	add_edge_graph2(v, h << 1 ^ 1);
}

void dijkstra_spf(int s) {
	fill(pi, pi + n_nodes, INF);
	pi[s] = 0;
	heap_insert(s);
	while (pq_size) {
		adj_node* curr;
		int u = heap_extract();
		int v;
		int h, h_, dist, dist2 = kk[u] + 1;

		for (curr = aa_[u].next; curr; curr = curr->next) {
			if (CAP[h_ = curr->node]) {
				h = h_ >> 1;
				dist = pi[u] + ((h_ & 1) == 0 ? COST_red[h] : -COST_red[h]);
				v = u ^ UV[h];
				if (pi[v] == INF) {
					pi[v] = dist;
					kk[v] = dist2;
					bb[v] = h_;
					heap_insert(v);
				} else if (pi[v] > dist || (pi[v] == dist && kk[v] > dist2)) {
					pi[v] = dist;
					kk[v] = dist2;
					bb[v] = h_;
					heap_up(v);
				}
			}
		}
	}
}

void augment_path(int s, int t) {
	int u, h, h_;
	for (u = t; u != s; u ^= UV[h]) {
		h = (h_ = bb[u]) >> 1;
		CAP[h_]--;
		CAP[h_ ^ 1]++;
	}
}

int min_cost_flow(int source, int sink) {
	int total_cost, idx;
	copy(COST, COST + m_edges, COST_red);
	while (1) {
		dijkstra_spf(source);
		if (pi[sink] == INF) break;
		augment_path(source, sink);
		for (idx = 0; idx < m_edges; idx++) {
			int u = U[idx], v = V[idx];
			if (pi[u] != INF && pi[v] != INF)
				COST_red[idx] += pi[u] - pi[v];
		}
	}
	total_cost = 0;
	for (idx = 0; idx < m_edges; idx++)
		total_cost += COST[idx] * CAP[idx << 1 ^ 1];
	return total_cost;
}

int main() {
	vector<int> initials(MAXK);
	int n, m, k, c, d, t, h, i, j, s, u, v, x;
	scanf("%d%d%d%d%d", &n, &m, &k, &c, &d);
	for (h = 0; h < k; h++) {
		scanf("%d", &initials[h]);
		initials[h]--;
	}
	while (m--) {
		scanf("%d%d", &i, &j);
		i--; j--;
		add_edge(i, j); add_edge(j, i);
	}
	t = n + k + 1;
	n_nodes = n * t + 1;
	m_edges = 0;
	for (i = 0; i < n; i++) {
		for (s = 0; s < t - 1; s++) {
			adj_node* curr;
			u = i * t + s;
			for (curr = aa[i].next; curr; curr = curr->next) {
				j = curr->node;
				v = j * t + s + 1;
				for (x = 1; x <= k; x++)
					add_link(u, v, 1, c + (x * 2 - 1) * d);
			}
		}
	}
	for (i = 0; i < n; i++) {
		for (s = 0; s < t - 1; s++) {
			u = i * t + s;
			v = u + 1;
			add_link(u, v, k, i == 0 ? 0 : c);
		}
	}
	for (h = 0; h < k; h++)
		add_link(n_nodes - 1, initials[h] * t + 0, 1, 0);
	printf("%d\n", min_cost_flow(n_nodes - 1, 0 * t + t - 1));
	return 0;
}
